int update_cc_node(CClassNode *cc, OnigCodePoint *vs, enum CCVALTYPE *type, enum CCSTATE *state, ScanEnv *env) {
    int r = 0;

    switch (*state) {
        case CC_INIT:
            if (*type == CCVAL_BITMAP) {
                if (onig_cclass_add_bitmap(cc, *vs, env) != 0) {
                    return ONIGERR_MEMORY;
                }
            } else {
                cc->range[0].s = *vs;
                *state = CC_RANGE_S;
            }
            break;

        case CC_RANGE_S:
            if (*vs < cc->range[0].s) {
                return ONIGERR_INVALID_RANGE;
            }
            cc->range[0].e = *vs;
            *state = CC_END;
            break;

        case CC_END:
            return ONIGERR_INVALID_RANGE;
            break;

        default:
            return ONIGERR_INVALID_ARGUMENT;
    }

    return r;
}

int update_char_class_node(CClassNode* cc, OnigCodePoint* vs, enum CCVALTYPE* type, enum CCSTATE* state, ScanEnv* env) {
    if (*state == CCSTATE_END) {
        return ONIGERR_INVALID_RANGE;
    }

    switch (*state) {
        case CCSTATE_INIT:
            cc->type = CC_TYPE_NORMAL;
            cc->range = NULL;
            *state = CCSTATE_FIRST;
            break;

        case CCSTATE_FIRST:
            if (cc->range) {
                onig_free(cc->range);
            }
            cc->range = (CodeRange*)onig_malloc(sizeof(CodeRange));
            if (!cc->range) {
                return ONIGERR_MEMORY;
            }
            cc->range->s = *vs;
            cc->range->e = *vs;
            *state = CCSTATE_SECOND;
            break;

        case CCSTATE_SECOND:
            if (cc->range->s > *vs) {
                return ONIGERR_INVALID_RANGE;
            }
            cc->range->e = *vs;
            *state = CCSTATE_END;
            break;
    }

    return 0;
}

int update_cclass_node(CClassNode *cc, OnigCodePoint *vs, enum CCVALTYPE *type, enum CCSTATE *state, ScanEnv *env) {
  if (*state == CCSTATE_END) {
    return ONIGERR_INVALID_RANGE;
  }

  if (*state == CCSTATE_INIT) {
    cc->type = *type;
    if (*type == CCVAL_BITMAP) {
      onig_bitten_set_bit(cc->bitmap, *vs);
    } else {
      cc->range[0] = *vs;
      cc->range[1] = ONIG_CHAR_CODE_EOT;
    }
    *state = CCSTATE_FIRST;
  } else if (*state == CCSTATE_FIRST) {
    if (*type != cc->type) {
      return ONIGERR_TYPE_MISMATCH;
    }

    if (*type == CCVAL_BITMAP) {
      onig_bitten_set_bit(cc->bitmap, *vs);
    } else {
      if (cc->range[0] > *vs) {
        return ONIGERR_INVALID_RANGE;
      }
      cc->range[1] = *vs;
      *state = CCSTATE_END;
    }
  }

  return 0;
}

int update_cclass_node(CClassNode* cc, OnigCodePoint* vs, enum CCVALTYPE* type, enum CCSTATE* state, ScanEnv* env) {
    int r = 0;

    if (*state == CCSTATE_END) {
        return ONIGERR_INVALID_RANGE;
    }

    if (*state == CCSTATE_INIT) {
        cc->type = *type;
        cc->init = TRUE;
        if (*type == CCVAL_BITMAP) {
            cc->bitmap = BITSET_NEW();
            if (cc->bitmap == NULL)
                return ONIGERR_MEMORY;
            BITSET_PUT(cc->bitmap, *vs);
        } else {
            cc->range[0] = *vs;
            cc->range[1] = ONIG_CCODE_END;
        }
        *state = CCSTATE_ADD;
    } else if (*state == CCSTATE_ADD) {
        if (*type == CCVAL_BITMAP) {
            BITSET_PUT(cc->bitmap, *vs);
        } else {
            if (*vs < cc->range[1]) {
                r = ONIGERR_INVALID_RANGE;
            } else {
                cc->range[1] = *vs;
                *state = CCSTATE_END;
            }
        }
    }

    return r;
}

int update_char_class_node(CClassNode* cc, OnigCodePoint* vs, enum CCVALTYPE* type, enum CCSTATE* state, ScanEnv* env) {
    int r = 0;

    switch (*state) {
        case CC_INIT:
            if (*type == CC_CCLASS_BITMAP) {
                if ((r = cclass_add_char(cc, *vs, env)) != 0)
                    return r;
            } else {
                cc->code_range[0].s = *vs;
                *state = CC_ADD_RSTART;
            }
            break;

        case CC_ADD_RSTART:
            if (*type == CC_CCLASS_BITMAP) {
                if ((r = cclass_add_char(cc, *vs, env)) != 0)
                    return r;
            } else {
                cc->code_range[0].e = *vs;
                *state = CC_ADD_REND;
            }
            break;

        case CC_ADD_REND:
            if (*vs != ONIG_CHAR_LAST) {
                cc->code_range[1].s = *vs;
                *state = CC_ADD_RSTART;
                *type = CC_CCLASS_CODE_RANGE;
            } else {
                *state = CC_END;
            }
            break;

        case CC_END:
            return ONIGERR_END_OF_RANGE;

        default:
            return ONIGERR_INVALID_ARGUMENT;
    }

    return r;
}
